import{_ as i,a0 as a,w as u,s,I as o,x as e,a1 as n,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"不編寫代碼也可以為開源項目做出貢獻 | LCTT x X-CMD","titleTemplate":false,"description":"不編寫代碼也可以為開源項目做出貢獻 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"不編寫代碼也可以為開源項目做出貢獻 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"不編寫代碼也可以為開源項目做出貢獻 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230309.1 ⭐️ Contribute to open source without code","title":"不編寫代碼也可以為開源項目做出貢獻","tag":"202303","desc":""},"relativePath":"202303/20230309.1 ⭐️ Contribute to open source without code.md","filePath":"[post].md"}'),d={name:"202303/20230309.1 ⭐️ Contribute to open source without code.md"};function h(m,t,f,T,b,C){const l=a("Link");return u(),s("div",null,[t[26]||(t[26]=o("h1",{id:"不編寫代碼也可以為開源項目做出貢獻",tabindex:"-1"},[e("不編寫代碼也可以為開源項目做出貢獻 "),o("a",{class:"header-anchor",href:"#不編寫代碼也可以為開源項目做出貢獻","aria-label":"Permalink to “不編寫代碼也可以為開源項目做出貢獻”"},"​")],-1)),t[27]||(t[27]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202303/16/231703lt3v8fw7t85uya30.jpg",alt:""})],-1)),t[28]||(t[28]=o("blockquote",null,[o("p",null,"如果你想通過非代碼貢獻成為一個提交者，或者沒有時間做代碼貢獻，那麼第一步就是加入社區。")],-1)),t[29]||(t[29]=o("p",null,"對於不同的人來説，開源“社區”意味着不同的東西。我認為開源有點像“愛情”，因為它是關於人和關係的。把開源當作一個社區，因為沒有人，就沒有源代碼，無論是開源還是閉源。",-1)),o("p",null,[t[2]||(t[2]=e("我是 ",-1)),n(l,{href:"https://dolphinscheduler.apache.org/en-us"},{default:p(()=>[...t[0]||(t[0]=[e("Apache DolphinScheduler",-1)])]),_:1}),t[3]||(t[3]=e(" 社區的成員。由於該項目有意保持低代碼，因此它吸引了許多 ",-1)),n(l,{href:"https://opensource.com/article/21/2/what-technical"},{default:p(()=>[...t[1]||(t[1]=[e("非軟件開發人員",-1)])]),_:1}),t[4]||(t[4]=e("。有時，那些不編寫代碼的人不確定是否有一種有意義的方式來為主要由源代碼組成的開源項目做出貢獻。我的經驗告訴我，有，我將在本文中解釋原因。",-1))]),t[30]||(t[30]=r('<h3 id="向社區做出貢獻" tabindex="-1">向社區做出貢獻 <a class="header-anchor" href="#向社區做出貢獻" aria-label="Permalink to “向社區做出貢獻”">​</a></h3><p>在 Apache DolphinScheduler 項目中，我主要負責全球運營、影響力和社區關懷。</p><p>一些人會説項目是樹而開源是土壤。這是一個恰當的比喻，它説明了積極培育你想要幫助成長的東西的重要性。</p><p>我有一個更簡單的想法：盡一切可能使其變得更好。</p><p>一個社區需要不斷的關注，不是因為它很貪心，而是因為它是生活的一部分。社區是你身邊的人，無論是物理空間還是在線空間。</p><p>自從加入開源社區以來，我已經獨立發起並組織了一些活動，包括：</p><ul><li>平均每月在中國舉辦一次會議。</li><li>建議社區參與大數據領域內的技術分享。</li><li>協調了中國“大數據”領域幾乎所有的開源項目，與這些社區進行了個別訪問和交流。</li></ul><p>在我看來，一個優秀的項目應該在一個良好的生態系統中成長。社區需要走出去，交換想法，分享資源，並與其他優秀的社區合作。每個人都應該感受到社區在工作中帶來的好處。</p><p>我的海外擴張遵循相同的模式。當然，由於文化和語言的差異，這樣做很困難。這需要耗費精力，但這是值得的。</p><p>到目前為止，我們已經在包括美國、印度、新加坡、德國、法國、芬蘭等國家成功舉辦了會議。</p><p>所以我如何為 DolphinScheduler 做出貢獻？我是否向項目提交代碼？我是社區經理嗎？我有正式的職稱嗎？</p><p>我認為自己是一個助手。我促進溝通和聯繫，這與任何代碼貢獻一樣，都是 “Apache Way” 的一個例子。</p><h3 id="從-dolphinscheduler-開始" tabindex="-1">從 DolphinScheduler 開始 <a class="header-anchor" href="#從-dolphinscheduler-開始" aria-label="Permalink to “從 DolphinScheduler 開始”">​</a></h3>',13)),o("p",null,[t[6]||(t[6]=e("我第一次接觸開源是在開放原子基金會工作時，擔任開源教育運營經理。作為中國第一個開源基金會，開放原子運營了以 ",-1)),n(l,{href:"https://gitee.com/openharmony"},{default:p(()=>[...t[5]||(t[5]=[e("OpenHarmony",-1)])]),_:1}),t[7]||(t[7]=e(" 為代表的許多項目。",-1))]),t[31]||(t[31]=o("p",null,"我加入了 DolphinScheduler 社區並發現了一羣熱衷於分享知識、提供指導和支持，並熱衷於幫助其他人發現對他們自己的生活有用的工具的人。",-1)),o("p",null,[t[9]||(t[9]=e("DolphinScheduler 旨在成為一個擁有全球影響力的調度系統，幫助團隊以 ",-1)),n(l,{href:"https://opensource.com/article/22/5/practical-tips-agile"},{default:p(()=>[...t[8]||(t[8]=[e("敏捷",-1)])]),_:1}),t[10]||(t[10]=e(" 和高效的方式工作。",-1))]),t[32]||(t[32]=r('<h3 id="對社區的第一印象" tabindex="-1">對社區的第一印象 <a class="header-anchor" href="#對社區的第一印象" aria-label="Permalink to “對社區的第一印象”">​</a></h3><p>聽到社區對項目開發的抱怨是一件常見的事情。我們都會時不時地抱怨。也許你報告了一個錯誤，但開發人員沒有解決你的問題。或者，也許你有一個很棒的功能想法，但團隊忽略了它。如果你是一個開源社區的成員，你以前就聽到過這些不滿，如果你沒有，你最終會聽到。</p><p>我瞭解到，這些聲音對於開源社區來説都很重要。這是一個好現象，因為當你聽到這些反饋時，這意味着社區願意發現錯誤，報告它們，提出問題和回答問題。聽到這些抱怨可能會揭示項目結構中需要改進的地方。社區中是否有志願者可以回應錯誤報告並對它們進行分類，以便它們能夠被分配給正確的開發人員？是否有一個志願者組等待成立，以便迅速回應項目論壇或論壇中新人的問題？</p><p>開源項目的門口有一個招待員可以幫助邀請猶豫不決的社區成員。招待員還可以確保沒有“門檻”。每個人都受歡迎，每個人都有自己的貢獻，即使他們能提供的只是互相幫助的氛圍。</p><p>儘管你我都希望能為每個人解決技術問題，但這是不現實的。但任何人都願意幫助找到解決方案，這是社區的一個偉大優勢。這些用户自發地充當了社區的“客户服務”部門。</p><p>在 DolphinScheduler 項目中，我們有很多人（Yan Jiang、Xu Zhiwu、Zhang Qichen、Wang Yuxiang、Xiang Zihao、Yang Qiyu、Yang Jiahao、Gao Chufeng 和 Gao Feng，順序不分先後！）。即使他們不開發解決方案，他們也不遺餘力地尋找能夠開發解決方案的人。</p><h3 id="給社區的話" tabindex="-1">給社區的話 <a class="header-anchor" href="#給社區的話" aria-label="Permalink to “給社區的話”">​</a></h3><p>如果你希望通過非代碼貢獻成為提交者，或者沒有時間進行代碼貢獻，那麼第一步就是加入社區。沒有註冊表格或批准流程，但也沒有快速通道。你通過參與加入社區。你通過可靠且持續的參與與其他人建立關係。</p><p>我隨時都可以聊天，總是渴望談論全球活動組織、文檔、反饋等。</p><h3 id="成為提交者" tabindex="-1">成為提交者 <a class="header-anchor" href="#成為提交者" aria-label="Permalink to “成為提交者”">​</a></h3><p>Apache DolphinScheduler 面臨着許多挑戰。大多數公司，即使是支持開源的公司，也會選擇非開源的商業工具。我希望與社區合作伙伴一起，使 DolphinScheduler 成為世界級的調度系統。我希望每個人都可以收穫他們想要的技術成果，而 DolphinScheduler 可以幫助他們實現這一目標。</p><p>加入我們的社區，幫助我們推廣開放和敏捷的工作方式。或者找到一個需要你非編碼技能的項目。發現讓你的同齡人社區獲得力量是多麼酷和有趣！</p><hr>',13)),o("p",null,[t[12]||(t[12]=e("via: ",-1)),n(l,{href:"https://opensource.com/article/23/3/non-code-contribution-open-source"},{default:p(()=>[...t[11]||(t[11]=[e("https://opensource.com/article/23/3/non-code-contribution-open-source",-1)])]),_:1})]),o("p",null,[t[17]||(t[17]=e("作者：",-1)),n(l,{href:"https://opensource.com/users/debra-chen"},{default:p(()=>[...t[13]||(t[13]=[e("Debra Chen",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),n(l,{href:"https://github.com/lkxed/"},{default:p(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),n(l,{href:"https://github.com/Cubik65536"},{default:p(()=>[...t[15]||(t[15]=[e("Cubik65536",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),n(l,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:p(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:p(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const S